@dataclass
class LayoutSpec:
    """Which layout a workspace has: the argument of `workspace_set_layout`. A struct that starts with `size` may grow."""

    kind: LayoutKind = 0
    placement: int = 0
    cascade_step: float = 0.0
    vtable: Optional[Layout] = None

    @classmethod
    def of_floating(cls) -> LayoutSpec:
        # `GnoblinStdLayoutSpec.kind`: the library's own floating layout. A window is placed once when it joins the workspace and
        # is left where the user puts it.
        return cls(kind=LayoutKind.FLOATING)

    @classmethod
    def of_foreign(cls, vtable: Optional[Layout] = None) -> LayoutSpec:
        # `GnoblinStdLayoutSpec.kind`: a layout the shell implements, reached through `vtable`.
        return cls(kind=LayoutKind.FOREIGN, vtable=vtable)

    def _to_dyn(self) -> dict[str, Any]:
        return {
            "kind": self.kind,
            "placement": self.placement,
            "cascade_step": self.cascade_step,
            "vtable": None if self.vtable is None else _LayoutAdapter(self.vtable),
        }

    @classmethod
    def _from_dyn(cls, data: dict[str, Any]) -> LayoutSpec:
        return cls(
            kind=_b.kind(LayoutKind, data["kind"]),
            placement=data["placement"],
            cascade_step=data["cascade_step"],
        )

