@dataclass
class Option:
    """One named, typed value: an option of a built-in layout, an argument of one of its actions, or what an action answers.
    `layouts::LAYOUT_KINDS` declares which names exist and what type each has; the library refuses any other.
    """

    kind: ValueKind = 0
    flag: int = 0
    name: str = ""
    text: str = ""
    number: float = 0.0
    node: int = 0

    @classmethod
    def of_none(cls) -> Option:
        # `GnoblinStdOption.kind`: no value (an optional option that is not set, or an action that answers nothing).
        return cls(kind=ValueKind.NONE)

    @classmethod
    def of_bool(cls, flag: int = 0) -> Option:
        # `GnoblinStdOption.kind`: a boolean, in `flag`.
        return cls(kind=ValueKind.BOOL, flag=flag)

    @classmethod
    def of_number(cls, number: float = 0.0) -> Option:
        # `GnoblinStdOption.kind`: a number, in `number` (a whole number for an integer option).
        return cls(kind=ValueKind.NUMBER, number=number)

    @classmethod
    def of_enum(cls, number: float = 0.0) -> Option:
        # `GnoblinStdOption.kind`: the number of an enumeration member, in `number`.
        return cls(kind=ValueKind.ENUM, number=number)

    @classmethod
    def of_node(cls, node: int = 0) -> Option:
        # `GnoblinStdOption.kind`: a window, by node id, in `node`.
        return cls(kind=ValueKind.NODE, node=node)

    @classmethod
    def of_text(cls, text: str = "") -> Option:
        # `GnoblinStdOption.kind`: text, in `text`.
        return cls(kind=ValueKind.TEXT, text=text)

    def _to_dyn(self) -> dict[str, Any]:
        return {
            "kind": self.kind,
            "flag": self.flag,
            "name": self.name,
            "text": self.text,
            "number": self.number,
            "node": self.node,
        }

    @classmethod
    def _from_dyn(cls, data: dict[str, Any]) -> Option:
        return cls(
            kind=_b.kind(ValueKind, data["kind"]),
            flag=data["flag"],
            name=data["name"],
            text=data["text"],
            number=data["number"],
            node=data["node"],
        )

