@dataclass
class StyleEntry:
    """One element of a style list: a border, a shadow or a filter. The `kind` (`STD_ENTRY_*`) says which fields are read."""

    kind: EntryKind = 0
    inset: int = 0
    a: float = 0.0
    b: float = 0.0
    c: float = 0.0
    d: float = 0.0
    color: str = ""

    @classmethod
    def of_border(cls, a: float = 0.0, b: float = 0.0, color: str = "", inset: int = 0) -> StyleEntry:
        # `GnoblinStdStyleEntry.kind`: a border (`a` width, `b` offset, `color`, `inset`).
        return cls(kind=EntryKind.BORDER, a=a, b=b, color=color, inset=inset)

    @classmethod
    def of_shadow(cls, a: float = 0.0, b: float = 0.0, c: float = 0.0, d: float = 0.0, color: str = "", inset: int = 0) -> StyleEntry:
        # `GnoblinStdStyleEntry.kind`: a shadow (`a` x, `b` y, `c` blur, `d` spread, `color`, `inset`).
        return cls(kind=EntryKind.SHADOW, a=a, b=b, c=c, d=d, color=color, inset=inset)

    @classmethod
    def of_blur(cls, a: float = 0.0) -> StyleEntry:
        # `GnoblinStdStyleEntry.kind`: a blur filter (`a` radius).
        return cls(kind=EntryKind.BLUR, a=a)

    @classmethod
    def of_saturate(cls, a: float = 0.0) -> StyleEntry:
        # `GnoblinStdStyleEntry.kind`: a saturate filter (`a` amount).
        return cls(kind=EntryKind.SATURATE, a=a)

    @classmethod
    def of_brightness(cls, a: float = 0.0) -> StyleEntry:
        # `GnoblinStdStyleEntry.kind`: a brightness filter (`a` amount).
        return cls(kind=EntryKind.BRIGHTNESS, a=a)

    @classmethod
    def of_contrast(cls, a: float = 0.0) -> StyleEntry:
        # `GnoblinStdStyleEntry.kind`: a contrast filter (`a` amount).
        return cls(kind=EntryKind.CONTRAST, a=a)

    def _to_dyn(self) -> dict[str, Any]:
        return {
            "kind": self.kind,
            "inset": self.inset,
            "a": self.a,
            "b": self.b,
            "c": self.c,
            "d": self.d,
            "color": self.color,
        }

    @classmethod
    def _from_dyn(cls, data: dict[str, Any]) -> StyleEntry:
        return cls(
            kind=_b.kind(EntryKind, data["kind"]),
            inset=data["inset"],
            a=data["a"],
            b=data["b"],
            c=data["c"],
            d=data["d"],
            color=data["color"],
        )

class Layout:
    """The functions of a layout the shell implements. Every function gets the layout's `user` first."""

    def compute(self, cx: LayoutContext) -> Sequence[Placement]:
        """Places the workspace's tiled clients. Pure: the same context and the same options give the same placements."""
        raise NotImplementedError

    # Optional: `def client_added(self, cx: LayoutContext, client: int) -> None`
    #   A client joined the workspace.
    # Optional: `def client_removed(self, cx: LayoutContext, client: int) -> None`
    #   A client left the workspace.
    # Optional: `def area_changed(self, old: Rect, new: Rect) -> None`
    #   The workspace's area changed.
    # Optional: `def clients_swapped(self, a: int, b: int) -> None`
    #   Two clients traded places in the workspace's order.
    # Optional: `def revision(self) -> int`
    #   The layout's revision: absent means the layout never changes by itself and the shell calls `workspace_invalidate`.
    # Optional: `def find_split(self, client: int, x: float, y: float) -> Optional[Split]`
    #   The divider a drag that pressed a client at a point would move. Absent: the layout has no dividers.
    # Optional: `def set_split(self, token: int, ratio: float, cross_ratio: float) -> None`
    #   Moves the dividers `find_split` returned.
    # Optional: `def reset_split(self, token: int) -> None`
    #   Puts the dividers `find_split` returned back as they were.

class _LayoutAdapter:
    """Presents a `Layout` to the native layer: the records of each call as classes."""

    def __init__(self, target: Any) -> None:
        self._target = target
        if hasattr(target, "compute"):
            self.compute = lambda cx: [_b.dyn(item) for item in (target.compute(LayoutContext._from_dyn(cx)) or ())]
        if hasattr(target, "client_added"):
            self.client_added = lambda cx, client: target.client_added(LayoutContext._from_dyn(cx), client)
        if hasattr(target, "client_removed"):
            self.client_removed = lambda cx, client: target.client_removed(LayoutContext._from_dyn(cx), client)
        if hasattr(target, "area_changed"):
            self.area_changed = lambda old, new: target.area_changed(Rect._from_dyn(old), Rect._from_dyn(new))
        if hasattr(target, "clients_swapped"):
            self.clients_swapped = lambda a, b: target.clients_swapped(a, b)
        if hasattr(target, "revision"):
            self.revision = lambda : target.revision()
        if hasattr(target, "find_split"):
            self.find_split = lambda client, x, y: _b.dyn(target.find_split(client, x, y))
        if hasattr(target, "set_split"):
            self.set_split = lambda token, ratio, cross_ratio: target.set_split(token, ratio, cross_ratio)
        if hasattr(target, "reset_split"):
            self.reset_split = lambda token: target.reset_split(token)

class Collection(_b.Handle):
    """A live collection of clients, outputs or workspaces: a root, a workspace's clients, or a selection of another
    collection. Zero is nil.
    """

    __slots__ = ("handle",)

    def __init__(self, handle: int | Collection) -> None:
        self.handle = _b.ident(handle)

    @staticmethod
    def root(kind: int) -> Optional[Collection]:
        """Writes the root collection of `kind` (`STD_COLLECTION_*`) to `out`. The same handle every time."""
        raw = _call("collection_root", _b.dyn(kind))
        return _b.wrap(Collection, raw)

    def where(self, terms: Sequence[QueryTerm | dict[str, Any]]) -> Optional[Collection]:
        """Makes the live selection of `parent` that holds the members whose properties match `terms`, and writes it to `out`.
        An unknown key is `E_NO_SUCH_MEMBER`.
        """
        raw = _call("collection_where", self.handle, _b.dyn(terms))
        return _b.wrap(Collection, raw)

    def kind(self) -> int:
        """Writes the kind of members the collection holds (`STD_COLLECTION_*`)."""
        raw = _call("collection_kind", self.handle)
        return raw

    def len(self) -> int:
        """Writes the number of members."""
        raw = _call("collection_len", self.handle)
        return raw

    def members(self) -> list[int]:
        """Writes the members, in order, to `out`. The array is valid until the next call into the library on this thread."""
        raw = _call("collection_members", self.handle)
        return list(raw)

    def contains(self, member: int) -> bool:
        """1 when `member` is in the collection now, 0 when it is not, or a negative error."""
        raw = _call("collection_contains", self.handle, _b.dyn(member))
        return bool(raw)

    def listen(self, event: int, flags: int, cb: Callable[[Event], Any]) -> Registration:
        """Calls `cb` for `event` of the collection (`STD_EVENT_*`): `STD_EVENT_ADDED` and `STD_EVENT_REMOVED` for its
        membership, any other for the members it holds. Zero on failure, with `user` not adopted. Never called inside this call.
        """
        raw = _call("collection_listen", self.handle, _b.dyn(event), _b.dyn(flags), _b.listener(cb, (Event._from_dyn,)))
        return Registration(raw)

    def add(self, member: int) -> int:
        """Adds `member` to a collection the shell may change (a workspace's clients, or the workspaces): on a workspace's
        clients this moves the client from its workspace. `E_REFUSED` for any other collection.
        """
        raw = _call("collection_add", self.handle, _b.dyn(member))
        return raw

    def remove(self, member: int) -> bool:
        """Removes `member`: 1 when it was removed, 0 when it was absent or refused (the last workspace stays)."""
        raw = _call("collection_remove", self.handle, _b.dyn(member))
        return bool(raw)

    def clear(self) -> int:
        """Removes every member without closing any window."""
        raw = _call("collection_clear", self.handle)
        return raw

    def swap(self, a: int, b: int) -> int:
        """Trades the places of two members in the collection's order. For a workspace's clients its layout hears of it."""
        raw = _call("collection_swap", self.handle, _b.dyn(a), _b.dyn(b))
        return raw

class Client(_b.Handle):
    """A node of the tree: the functions of `client` that take one."""

    __slots__ = ("node",)

    def __init__(self, node: int | Client) -> None:
        self.node = _b.ident(node)

    def workspace(self) -> Optional[Workspace]:
        """Writes the workspace a client is on, or zero."""
        raw = _call("client_workspace", self.node)
        return _b.wrap(Workspace, raw)

    def move_to_workspace(self, workspace: Workspace | int) -> bool:
        """Moves a client to a workspace: 1 when it moved, 0 when it was refused (the client is gone, fullscreen, a dialog,
        already there, or the workspace is not added).
        """
        raw = _call("client_move_to_workspace", self.node, _b.dyn(workspace))
        return bool(raw)

    def set_floating(self, floating: int) -> int:
        """Marks a client floating: a layout leaves it where it is."""
        raw = _call("client_set_floating", self.node, _b.dyn(floating))
        return raw

    def is_floating(self) -> bool:
        """1 when the shell marked the client floating."""
        raw = _call("client_is_floating", self.node)
        return bool(raw)

    def state(self) -> ClientState:
        """Writes what the library remembers about a client: frame inset, size limits, floating rectangle and snap."""
        raw = _call("client_state", self.node)
        return ClientState._from_dyn(raw)

    def set_state(self, state: ClientState | dict[str, Any]) -> int:
        """Sets the frame inset, the size limits and the floating rectangle of a client. A change of the inset makes the client's
        workspace compute again.
        """
        raw = _call("client_set_state", self.node, _b.dyn(state))
        return raw

    def snap(self, zone: int, area: Rect | dict[str, Any], edge_tiling: int) -> bool:
        """Tiles a client to `zone` (`STD_SNAP_*`) of `area`, less its frame inset: 1 when it snapped, 0 when it was refused
        (`edge_tiling` is zero, or the zone does not tile). A maximised client floats first; a client keeps the rectangle it
        first floated at while it stays snapped.
        """
        raw = _call("client_snap", self.node, _b.dyn(zone), _b.dyn(area), _b.dyn(edge_tiling))
        return bool(raw)

    def unsnap(self, forget: int) -> bool:
        """Puts a snapped client back where it floated: 1 when it was snapped, 0 when it was not. With `forget` the snapped state
        ends without moving the client.
        """
        raw = _call("client_unsnap", self.node, _b.dyn(forget))
        return bool(raw)

    def areas(self) -> Areas:
        """Writes the output a client is on and its work area. A client whose workspace no output shows is on the primary output;
        zero asks for the primary output itself.
        """
        raw = _call("client_areas", self.node)
        return Areas._from_dyn(raw)

    def restore_snap(self, zone: int, floating: Rect | dict[str, Any]) -> int:
        """Gives a client the snapped state a reload takes back: `zone` (`STD_SNAP_*`) and the rectangle `client_unsnap` puts it back to.
        Nothing moves: the caller put the window where it was. `E_NO_SUCH_NODE` for a node that is not a client.
        """
        raw = _call("client_restore_snap", self.node, _b.dyn(zone), _b.dyn(floating))
        return raw

class Workspace(_b.Handle):
    """A workspace, by the library's own id. Zero is nil; an id is never reused in one process."""

    __slots__ = ("handle",)

    def __init__(self, handle: int | Workspace) -> None:
        self.handle = _b.ident(handle)

    @staticmethod
    def new(spec: WorkspaceSpec | dict[str, Any]) -> Optional[Workspace]:
        """Makes a workspace and writes its handle to `out`. It is not in the list of added workspaces until `workspace_add`."""
        raw = _call("workspace_new", _b.dyn(spec))
        return _b.wrap(Workspace, raw)

    @staticmethod
    def by_id(id: str) -> Optional[Workspace]:
        """Writes the added workspace with this id to `out`; `E_NO_SUCH_MEMBER` when there is none."""
        raw = _call("workspace_by_id", _b.dyn(id))
        return _b.wrap(Workspace, raw)

    def info(self) -> WorkspaceInfo:
        """Fills `out` with what the workspace is now."""
        raw = _call("workspace_info", self.handle)
        return WorkspaceInfo._from_dyn(raw)

    def add(self) -> int:
        """Adds the workspace to the list and gives it the windows that wait for one. `E_BUSY` when a workspace with its id is
        there already.
        """
        raw = _call("workspace_add", self.handle)
        return raw

    def remove(self) -> bool:
        """Takes the workspace out of the list: 1 when it left, 0 when it was refused (the last workspace stays). Its windows
        move to the workspace before it (after it, for the first) and none is closed.
        """
        raw = _call("workspace_remove", self.handle)
        return bool(raw)

    def set_name(self, name: str) -> int:
        """Sets the name people see."""
        raw = _call("workspace_set_name", self.handle, _b.dyn(name))
        return raw

    def set_gaps(self, inner: float, outer: float) -> int:
        """Sets the gaps; the workspace computes again."""
        raw = _call("workspace_set_gaps", self.handle, _b.dyn(inner), _b.dyn(outer))
        return raw

    def set_layout(self, spec: LayoutSpec | dict[str, Any]) -> int:
        """Gives the workspace another layout. The windows stay where they are until it computes."""
        raw = _call("workspace_set_layout", self.handle, _b.dyn(spec))
        return raw

    def invalidate(self) -> int:
        """Tells the workspace that its layout changed in a way its revision did not show: it computes again."""
        raw = _call("workspace_invalidate", self.handle)
        return raw

    def clients(self) -> Optional[Collection]:
        """Writes the collection of the workspace's clients, which the shell may change."""
        raw = _call("workspace_clients", self.handle)
        return _b.wrap(Collection, raw)

    def show(self, show: Show | dict[str, Any]) -> int:
        """Shows the workspace on an output, swapping it with the one that output showed, and slides the windows when
        `duration_ms` asks. `E_REFUSED` when the workspace is not added or no output can show it.
        """
        raw = _call("workspace_show", self.handle, _b.dyn(show))
        return raw

    def walk(self, step: int) -> int:
        """Moves the keyboard `step` windows along the workspace's windows: nothing moves past either end."""
        raw = _call("workspace_walk", self.handle, _b.dyn(step))
        return raw

    def find_split(self, client: int, x: float, y: float) -> Optional[Split]:
        """The divider that a drag which pressed `client` at (`x`, `y`) would move, from the layout of the workspace the client is
        on: 1 when it wrote one to `out`, 0 when the layout has none there (or none at all).
        """
        raw = _call("workspace_find_split", self.handle, _b.dyn(client), _b.dyn(x), _b.dyn(y))
        return None if raw is None else Split._from_dyn(raw)

    def set_split(self, token: int, ratio: float, cross_ratio: float) -> int:
        """Moves the dividers of the drag `token` of the workspace's layout and makes the workspace compute again."""
        raw = _call("workspace_set_split", self.handle, _b.dyn(token), _b.dyn(ratio), _b.dyn(cross_ratio))
        return raw

    def reset_split(self, token: int) -> int:
        """Puts the dividers of the drag `token` back as they were and makes the workspace compute again."""
        raw = _call("workspace_reset_split", self.handle, _b.dyn(token))
        return raw

    def set_layout_kind(self, kind: int, options: Sequence[Option | dict[str, Any]]) -> int:
        """Gives the workspace the built-in layout `kind` (`STD_BUILTIN_*`) with the options given; an option not given has the
        default `layouts::LAYOUT_KINDS` declares. Replaces the layout; its windows stay where they are until it computes.
        `E_NO_SUCH_MEMBER` for an unknown option, `E_TYPE` for a value of the wrong type or out of range.
        """
        raw = _call("workspace_set_layout_kind", self.handle, _b.dyn(kind), _b.dyn(options))
        return raw

    def layout_set(self, option: Option | dict[str, Any]) -> int:
        """Changes one option of the workspace's built-in layout. The tree the layout keeps is kept; the workspace computes again.
        `E_REFUSED` when the workspace's layout is not a built-in one.
        """
        raw = _call("workspace_layout_set", self.handle, _b.dyn(option))
        return raw

    def layout_get(self, name: str) -> Option:
        """Writes one option of the workspace's built-in layout to `out`."""
        raw = _call("workspace_layout_get", self.handle, _b.dyn(name))
        return Option._from_dyn(raw)

    def layout_act(self, action: str, args: Sequence[Option | dict[str, Any]]) -> Option:
        """Runs an action of the workspace's built-in layout with the arguments given and writes what it answers to `out`
        (`STD_VALUE_NONE` when it answers nothing). The workspace computes again when the action changed the layout.
        """
        raw = _call("workspace_layout_act", self.handle, _b.dyn(action), _b.dyn(args))
        return Option._from_dyn(raw)

    def layout_kind(self) -> int:
        """Writes the `STD_BUILTIN_*` kind of the workspace's layout, or zero when it is the floating layout or a foreign one."""
        raw = _call("workspace_layout_kind", self.handle)
        return raw

    def restore_client(self, client: int, arrived: int) -> bool:
        """Puts a client on a workspace as a reload gives it back: it moves like `client_move_to_workspace` (its dialogs go with it), but
        it is not refitted, and a layout is told it arrived only when `arrived` is nonzero. 1 when it moved, 0 when it was refused
        (the client is gone or already there, or the workspace is not added).
        """
        raw = _call("workspace_restore_client", self.handle, _b.dyn(client), _b.dyn(arrived))
        return bool(raw)

class Policy(_b.Handle):
    """Functions of `policy` that need no handle."""

    @staticmethod
    def outputs(policy: OutputPolicy | dict[str, Any]) -> int:
        """Sets how the outputs share workspaces."""
        raw = _call("policy_outputs", _b.dyn(policy))
        return raw

    @staticmethod
    def workspaces(policy: WorkspacePolicy | dict[str, Any]) -> int:
        """Sets where workspaces come from."""
        raw = _call("policy_workspaces", _b.dyn(policy))
        return raw

class Output(_b.Handle):
    """A node of the tree: the functions of `output` that take one."""

    __slots__ = ("node",)

    def __init__(self, node: int | Output) -> None:
        self.node = _b.ident(node)

    def workspace(self) -> Optional[Workspace]:
        """Writes the workspace an output shows, or zero."""
        raw = _call("output_workspace", self.node)
        return _b.wrap(Workspace, raw)

    def info(self) -> OutputInfo:
        """Fills `out` with what the desk knows about an output: whether it can show a workspace, which one it shows, its rectangle and
        the area a layout tiles in on it. `E_NO_SUCH_NODE` for a node that is not an output the library tracks.
        """
        raw = _call("output_info", self.node)
        return OutputInfo._from_dyn(raw)

    def set_insets(self, top: float, bottom: float) -> int:
        """Sets the room the shell's own bars take from the top and the bottom of an output. A layout tiles in what is left, so
        every workspace computes again when it changes. `E_NO_SUCH_NODE` for a node that is not an output the library tracks.
        """
        raw = _call("output_set_insets", self.node, _b.dyn(top), _b.dyn(bottom))
        return raw

    @staticmethod
    def span(span: Span | dict[str, Any]) -> int:
        """Makes the desk of the span's lead show one workspace over its members (the desks of the other members show nothing of
        their own), or ends the lead's span. Asking for the span that holds changes nothing.
        """
        raw = _call("output_span", _b.dyn(span))
        return raw

class Easing(_b.Handle):
    """Functions of `easing` that need no handle."""

    @staticmethod
    def sample(easing: int, t: float) -> float:
        """Writes `easing(t)` to `out`: the CSS timing function `easing` (`STD_EASING_*`) at progress `t`."""
        raw = _call("easing_sample", _b.dyn(easing), _b.dyn(t))
        return raw

class Transition(_b.Handle):
    """A transition (a set of timed writes that play together), by the library's own id. Zero is nil; an id is never reused in
    one process.
    """

    __slots__ = ("handle",)

    def __init__(self, handle: int | Transition) -> None:
        self.handle = _b.ident(handle)

    @staticmethod
    def begin(options: TransitionOptions | dict[str, Any]) -> int:
        """Starts staging: property writes (the shell's through `transition_set`, and the library's own layout and style passes)
        are held until `transition_commit`. `E_BUSY` while another transition is being staged.
        """
        raw = _call("transition_begin", _b.dyn(options))
        return raw

    @staticmethod
    def set(node: int, key: str, value: Prop | dict[str, Any]) -> int:
        """Stages a write of `key` of `node` (checked at once). Without a transition being staged the write goes straight to the tree."""
        raw = _call("transition_set", _b.dyn(node), _b.dyn(key), _b.dyn(value))
        return raw

    @staticmethod
    def get(node: int, key: str) -> Prop:
        """Reads `key` of `node`: the staged value while a transition is staged, else the tree's."""
        raw = _call("transition_get", _b.dyn(node), _b.dyn(key))
        return Prop._from_dyn(raw)

    @staticmethod
    def commit() -> Optional[Transition]:
        """Runs the layout and style passes against the staged state, ends staging and sends the writes as timed writes joined to
        one `tween` node. Writes the transition to `out`.
        """
        raw = _call("transition_commit")
        return _b.wrap(Transition, raw)

    @staticmethod
    def abort() -> int:
        """Ends staging and drops what was staged."""
        raw = _call("transition_abort")
        return raw

    @staticmethod
    def animate(node: int, key: str, value: Prop | dict[str, Any], options: TransitionOptions | dict[str, Any]) -> Optional[Transition]:
        """One timed write of its own: writes `key` of `node` over the options' duration, as a transition of that one property."""
        raw = _call("transition_animate", _b.dyn(node), _b.dyn(key), _b.dyn(value), _b.dyn(options))
        return _b.wrap(Transition, raw)

    def control(self, op: int, value: float) -> int:
        """Plays, pauses, reverses, seeks or cancels a transition (`STD_CONTROL_*`; `value` is the seek fraction). `E_BUSY` while a
        transition is being staged.
        """
        raw = _call("transition_control", self.handle, _b.dyn(op), _b.dyn(value))
        return raw

    def info(self) -> TransitionInfo:
        """Fills `out` with what the transition is now."""
        raw = _call("transition_info", self.handle)
        return TransitionInfo._from_dyn(raw)

    def finished(self, cb: Callable[[Event], Any]) -> Registration:
        """Calls `cb` once with a `STD_EVENT_TRANSITION_FINISHED` event when the transition ends (at once, from the next turn, when it
        has ended already). Zero on failure, with `user` not adopted.
        """
        raw = _call("transition_finished", self.handle, _b.listener(cb, (Event._from_dyn,)))
        return Registration(raw)

