class DwindleLayout(_b.BuiltinLayout):
    """A binary split tree that places windows as Hyprland's dwindle layout does: a new window splits the cell of the focused window in two. Ratios are fractions of the first child, 0.1 to 0.9 (Hyprland's 1.0 is 0.5 here)."""

    KIND: ClassVar[int] = 4
    SHAPES: ClassVar[dict[str, tuple[int, str, bool]]] = {
        "split": (3, "number", True),
        "ratio": (2, "number", False),
        "gap": (2, "number", False),
        "force_split": (3, "number", True),
        "preserve_split": (1, "flag", False),
        "smart_split": (1, "flag", False),
        "smart_resizing": (1, "flag", False),
        "permanent_direction_override": (1, "flag", False),
        "split_width_multiplier": (2, "number", False),
        "use_active_for_splits": (1, "flag", False),
        "split_bias": (3, "number", True),
        "pointer": (3, "number", True),
        "pointer_x": (2, "number", False),
        "pointer_y": (2, "number", False),
    }
    ACTION_SHAPES: ClassVar[dict[str, tuple[int, str, bool]]] = {
        "toggle_split->": (1, "flag", False),
        "swap_split->": (1, "flag", False),
        "rotate_split.angle": (2, "number", False),
        "rotate_split->": (1, "flag", False),
        "move_to_root.stable": (1, "flag", False),
        "move_to_root->": (1, "flag", False),
        "split_ratio.amount": (2, "number", False),
        "split_ratio->": (1, "flag", False),
        "set_split_ratio.ratio": (2, "number", False),
        "set_split_ratio->": (1, "flag", False),
        "preselect.direction": (3, "number", True),
        "preselected->": (3, "number", True),
        "pseudotile.width": (2, "number", False),
        "pseudotile.height": (2, "number", False),
        "pseudotile->": (1, "flag", False),
        "is_pseudotiled.client": (4, "node", True),
        "is_pseudotiled->": (1, "flag", False),
    }
    DIVIDERS: ClassVar[bool] = True

    def __init__(self, *, split: DwindleSplit = DwindleSplit.ASPECT, ratio: float = 0.5, gap: Optional[float] = None, force_split: DwindleForceSplit = DwindleForceSplit.BY_POINTER, preserve_split: bool = False, smart_split: bool = False, smart_resizing: bool = True, permanent_direction_override: bool = False, split_width_multiplier: float = 1.0, use_active_for_splits: bool = True, split_bias: DwindleSplitBias = DwindleSplitBias.FIRST, pointer: DwindlePointer = DwindlePointer.NONE, pointer_x: Optional[float] = None, pointer_y: Optional[float] = None) -> None:
        super().__init__({"split": split, "ratio": ratio, "gap": gap, "force_split": force_split, "preserve_split": preserve_split, "smart_split": smart_split, "smart_resizing": smart_resizing, "permanent_direction_override": permanent_direction_override, "split_width_multiplier": split_width_multiplier, "use_active_for_splits": use_active_for_splits, "split_bias": split_bias, "pointer": pointer, "pointer_x": pointer_x, "pointer_y": pointer_y})

    @property
    def split(self) -> DwindleSplit:
        """Split direction for each new window."""
        return _b.kind(DwindleSplit, self._get("split"))

    @split.setter
    def split(self, value: DwindleSplit) -> None:
        self._set("split", value)

    @property
    def ratio(self) -> float:
        """The first child's share of every split that was not dragged or set, held to 0.1 to 0.9."""
        return self._get("ratio")

    @ratio.setter
    def ratio(self, value: float) -> None:
        self._set("ratio", value)

    @property
    def gap(self) -> Optional[float]:
        """The gap between tiles, replacing the workspace's inner gap; at least 0."""
        return self._get("gap")

    @gap.setter
    def gap(self, value: Optional[float]) -> None:
        self._set("gap", value)

    @property
    def force_split(self) -> DwindleForceSplit:
        """Where a new window goes in the cell it splits."""
        return _b.kind(DwindleForceSplit, self._get("force_split"))

    @force_split.setter
    def force_split(self, value: DwindleForceSplit) -> None:
        self._set("force_split", value)

    @property
    def preserve_split(self) -> bool:
        """Keeps each split's direction as it was made instead of following the shape of its cell."""
        return self._get("preserve_split")

    @preserve_split.setter
    def preserve_split(self, value: bool) -> None:
        self._set("preserve_split", value)

    @property
    def smart_split(self) -> bool:
        """Chooses the direction and side of a new window by the pointer's place in the cell it splits. Implies
        `preserve_split`. With no pointer it does nothing.
        """
        return self._get("smart_split")

    @smart_split.setter
    def smart_split(self, value: bool) -> None:
        self._set("smart_split", value)

    @property
    def smart_resizing(self) -> bool:
        """Which divider a split-resize drag moves. True: the divider nearest the press. False: both dividers that bound
        the window by its place in the tree.
        """
        return self._get("smart_resizing")

    @smart_resizing.setter
    def smart_resizing(self, value: bool) -> None:
        self._set("smart_resizing", value)

    @property
    def permanent_direction_override(self) -> bool:
        """Keeps a `preselect` choice for every new window until it is cleared, instead of once."""
        return self._get("permanent_direction_override")

    @permanent_direction_override.setter
    def permanent_direction_override(self, value: bool) -> None:
        self._set("permanent_direction_override", value)

    @property
    def split_width_multiplier(self) -> float:
        """A split goes side by side when the cell's width is at least its height times this; any finite number is taken,
        and it is held to 0.1 to 3.0 where it is used.
        """
        return self._get("split_width_multiplier")

    @split_width_multiplier.setter
    def split_width_multiplier(self, value: float) -> None:
        self._set("split_width_multiplier", value)

    @property
    def use_active_for_splits(self) -> bool:
        """True: a new window splits the focused window. False: it splits the window under the pointer, or the first
        window when there is no pointer.
        """
        return self._get("use_active_for_splits")

    @use_active_for_splits.setter
    def use_active_for_splits(self, value: bool) -> None:
        self._set("use_active_for_splits", value)

    @property
    def split_bias(self) -> DwindleSplitBias:
        """Which window of a new split gets `ratio`."""
        return _b.kind(DwindleSplitBias, self._get("split_bias"))

    @split_bias.setter
    def split_bias(self, value: DwindleSplitBias) -> None:
        self._set("split_bias", value)

    @property
    def pointer(self) -> DwindlePointer:
        """Where the pointer is read from. `force_split` by pointer, `smart_split` and `use_active_for_splits` read it
        when a window arrives.
        """
        return _b.kind(DwindlePointer, self._get("pointer"))

    @pointer.setter
    def pointer(self, value: DwindlePointer) -> None:
        self._set("pointer", value)

    @property
    def pointer_x(self) -> Optional[float]:
        """With `pointer` fixed: the point's x."""
        return self._get("pointer_x")

    @pointer_x.setter
    def pointer_x(self, value: Optional[float]) -> None:
        self._set("pointer_x", value)

    @property
    def pointer_y(self) -> Optional[float]:
        """With `pointer` fixed: the point's y."""
        return self._get("pointer_y")

    @pointer_y.setter
    def pointer_y(self, value: Optional[float]) -> None:
        self._set("pointer_y", value)

    def toggle_split(self) -> bool:
        """Turns the split above the focused window from side by side to top and bottom or back. A split that follows the
        shape of its cell takes its direction from the cell again at once, so this needs `preserve_split`. False when
        no window with a split above it has focus.
        """
        return self._act("toggle_split", [])

    def swap_split(self) -> bool:
        """Swaps the two halves of the split above the focused window. False when there is none."""
        return self._act("swap_split", [])

    def rotate_split(self, angle: float) -> bool:
        """Turns the split above the focused window: the first half goes from the left to the top to the right to the
        bottom. 180 swaps the halves. False when there is no split above the focused window.
        """
        return self._act("rotate_split", [("angle", angle)])

    def move_to_root(self, stable: bool) -> bool:
        """Makes the focused window a direct child of the root split: it takes the place of the root's other half, which
        goes where the window was. False when the window is alone or already a child of the root.
        """
        return self._act("move_to_root", [("stable", stable)])

    def split_ratio(self, amount: float) -> bool:
        """Changes the share of the split above the focused window by `amount`, held to 0.1 to 0.9. The split keeps the
        ratio, whatever the layout's `ratio` becomes. False when the window has no split above it.
        """
        return self._act("split_ratio", [("amount", amount)])

    def set_split_ratio(self, ratio: float) -> bool:
        """Sets the share of the split above the focused window to `ratio`, held to 0.1 to 0.9."""
        return self._act("set_split_ratio", [("ratio", ratio)])

    def preselect(self, direction: DwindleDirection) -> None:
        """Sets where the next window opens: left or up puts it first with a split that goes that way, right or down
        second. The split keeps its direction whatever its cell's shape. The choice is used once, unless
        `permanent_direction_override` is set; none clears it.
        """
        self._act("preselect", [("direction", direction)])

    def preselected(self) -> DwindlePreselected:
        """The direction `preselect` set for the next window, or none."""
        return _b.kind(DwindlePreselected, self._act("preselected", []))

    def pseudotile(self, width: Optional[float] = None, height: Optional[float] = None) -> bool:
        """Toggles pseudotiling of the focused window: it keeps its own size, centred in its cell and held to the cell's
        size, instead of filling the cell. The size is the one given, else the window's own size with its frame, else
        the size its cell has at the next compute. Answers whether the window is pseudotiled after the call; false
        also when no window with a tile has focus.
        """
        return self._act("pseudotile", [("width", width), ("height", height)])

    def is_pseudotiled(self, client: int) -> bool:
        """Whether the window is pseudotiled."""
        return self._act("is_pseudotiled", [("client", client)])

class StripLayout(_b.BuiltinLayout):
    """One column per window in a horizontal strip, with the focus kept in view. Columns sit edge to edge with no gap or margin. The view follows the focus unless `scroll_to` pinned it; a pin ends when the focused window changes. A new window opens right after the focused column, and the layout hands the keyboard to a neighbour when a window closes."""

    KIND: ClassVar[int] = 5
    SHAPES: ClassVar[dict[str, tuple[int, str, bool]]] = {
        "column": (2, "number", False),
    }
    ACTION_SHAPES: ClassVar[dict[str, tuple[int, str, bool]]] = {
        "scroll_to.offset": (2, "number", False),
        "pin->": (2, "number", False),
    }
    DIVIDERS: ClassVar[bool] = False

    def __init__(self, *, column: float = 0.5) -> None:
        super().__init__({"column": column})

    @property
    def column(self) -> float:
        """A column's width as a fraction of the strip's, held to 0.1 to 1."""
        return self._get("column")

    @column.setter
    def column(self, value: float) -> None:
        self._set("column", value)

    def scroll_to(self, offset: Optional[float] = None) -> None:
        """Scrolls the view to `offset` pixels and keeps it there until the focused window changes; with no offset the
        view follows the focus again.
        """
        self._act("scroll_to", [("offset", offset)])

    def focus_left(self) -> None:
        """Moves the keyboard one column left; at the first column nothing happens."""
        self._act("focus_left", [])

    def focus_right(self) -> None:
        """Moves the keyboard one column right; at the last column nothing happens."""
        self._act("focus_right", [])

    def pin(self) -> Optional[float]:
        """The view offset in pixels that `scroll_to` pinned, or absent while the view follows the focus."""
        return self._act("pin", [])

